import java.util.PriorityQueue;
import java.util.Queue;

// Example of using a priority queue for task scheduling in Java
public class TaskScheduler {
    public static void main(String[] args) {
        // Create a priority queue to simulate task scheduling
        Queue<String> taskQueue = new PriorityQueue<>();

        // Add tasks to the queue (priority is based on task importance)
        taskQueue.offer("High Priority Task");
        taskQueue.offer("Medium Priority Task");
        taskQueue.offer("Low Priority Task");

        // Step 1: Dequeue the highest priority task
        String highestPriorityTask = taskQueue.poll();
        System.out.println("Dequeued task: " + highestPriorityTask);

        // Step 2: Dequeue the next highest priority task
        String nextTask = taskQueue.poll();
        System.out.println("Dequeued task: " + nextTask);

        // Step 3: Dequeue the remaining task
        String lastTask = taskQueue.poll();
        System.out.println("Dequeued task: " + lastTask);
    }
}

