import java.util.PriorityQueue;
import java.util.Queue;

// Example of using a priority queue for task scheduling in Java
public class TaskScheduler {
    public static void main(String[] args) {
        // Create a priority queue to store tasks based on their priority
        Queue<Task> taskQueue = new PriorityQueue<>();

        // Add tasks to the queue with different priorities
        taskQueue.add(new Task("Task 1", 3)); // Priority 3
        taskQueue.add(new Task("Task 2", 1)); // Priority 1
        taskQueue.add(new Task("Task 3", 2)); // Priority 2

        // Dequeue and process tasks in priority order
        while (!taskQueue.isEmpty()) {
            Task currentTask = taskQueue.poll(); // Dequeue the task with the highest priority
            System.out.println("Processing task: " + currentTask.name + " (Priority: " + currentTask.priority + ")");
        }
    }
}

// Task class representing a task with a name and priority
class Task implements Comparable<Task> {
    String name;
    int priority;

    public Task(String name, int priority) {
        this.name = name;
        this.priority = priority;
    }

    // Compare tasks based on their priority
    @Override
    public int compareTo(Task other) {
        return Integer.compare(this.priority, other.priority);
    }
}

